  "Zones with “Over the cancel rate limit” on in Safety send no requests to drivers over it. Reasons marked “Doesn't count” never count ({0}). Scheduled rides also follow the late-cancel rule in Reservations. The acceptance rate has no rules.": "Zones with “Over the cancel rate limit” on in Safety send no requests to drivers over it. Reasons marked “Doesn't count” never count ({0}). Scheduled rides also follow the late-cancel rule in Reservations. The acceptance rate has no rules.",
