  "The panel is in {0}.": "The panel is in {0}.",
  "Switch the panel to {0}": "Switch the panel to {0}",
  "Switch the panel to English, French or Swedish. The choice is saved for you only, as in My profile.": "Switch the panel to English, French or Swedish. The choice is saved for you only, as in My profile.",
  // Pickup pay
  "A category keeps at least one range.": "A category keeps at least one range.",
  "{0} A farther range pays less per km than the one before it. Allowed, but check it is what you want.": "{0} A farther range pays less per km than the one before it. Allowed, but check it is what you want.",
  "Two separate sides. The driver gets pickup pay from Movera for the drive to the pickup, worked out from their live location each time an offer shows; the driver only sees the total. The rider pays a fixed pickup fee set here, the same whoever the driver is. Movera keeps the difference, and covers it when the driver came from far.": "Two separate sides. The driver gets pickup pay from Movera for the drive to the pickup, worked out from their live location each time an offer shows; the driver only sees the total. The rider pays a fixed pickup fee set here, the same whoever the driver is. Movera keeps the difference, and covers it when the driver came from far.",
  "Paid by Movera": "Paid by Movera",
  "{0} maximum per ride": "{0} maximum per ride",
  "Maximum per ride": "Maximum per ride",
  "{0} maximum pickup pay per ride": "{0} maximum pickup pay per ride",
  "No maximum": "No maximum",
  "{0} rider pickup fee": "{0} rider pickup fee",
  "Live rides (Radar & Exclusive)": "Live rides (Radar & Exclusive)",
  "{0} rider pickup fee for {1}": "{0} rider pickup fee for {1}",
  "{0} rider pickup fee amount for {1}": "{0} rider pickup fee amount for {1}",
  "Driver side: every km is paid at the rate of the range it falls in, and the minutes are split across the ranges in proportion to the km in each. Set a range to 0 to make it free. Ranges go up with no gaps; only the last can be \"and above\". The maximum per ride caps what all the ranges add up to.": "Driver side: every km is paid at the rate of the range it falls in, and the minutes are split across the ranges in proportion to the km in each. Set a range to 0 to make it free. Ranges go up with no gaps; only the last can be \"and above\". The maximum per ride caps what all the ranges add up to.",
  "Rider side: a fixed amount in the price, with no ranges. One for live rides (Radar and Exclusive) and one for reservations; when it is off the rider pays nothing for the pickup.": "Rider side: a fixed amount in the price, with no ranges. One for live rides (Radar and Exclusive) and one for reservations; when it is off the rider pays nothing for the pickup.",
  "{0} Reservations taken from the Scheduled rides list never get driver pickup pay. The rider's reservation pickup fee, when on, is paid either way.": "{0} Reservations taken from the Scheduled rides list never get driver pickup pay. The rider's reservation pickup fee, when on, is paid either way.",
  "Example ride kind": "Example ride kind",
  "Live ride": "Live ride",
  "Driver pickup pay · paid by Movera": "Driver pickup pay · paid by Movera",
  "{0}: {1} km × {2} + {3} min × {4}": "{0}: {1} km × {2} + {3} min × {4}",
  "Ranges add up to {0}; capped at the maximum": "Ranges add up to {0}; capped at the maximum",
  "The maximum of {0} is not reached within 300 km at this pace.": "The maximum of {0} is not reached within 300 km at this pace.",
