  // Radar · Exclusive · Reservations
  "A rule applies to all radar zones, several or one. The rule follows the radar zone the ride was sent to, never where a driver stands, so overlapping zones never clash. A rule naming a radar zone wins over the rule for all of them.": "A rule applies to all radar zones, several or one. The rule follows the radar zone the ride was sent to, never where a driver stands, so overlapping zones never clash. A rule naming a radar zone wins over the rule for all of them.",
  "All radar zones": "All radar zones",
  "Applies to: {0}": "Applies to: {0}",
  "Applies to{0}": "Applies to{0}",
  "Areas inside the zone, drawn on the map and saved. From Live or the Dashboard a waiting ride can be put on the radar of one area: the free drivers inside it see it. Zones are independent and may overlap, so start small and widen if nobody accepts. The whole zone needs no radar zone.": "Areas inside the zone, drawn on the map and saved. From Live or the Dashboard a waiting ride can be put on the radar of one area: the free drivers inside it see it. Zones are independent and may overlap, so start small and widen if nobody accepts. The whole zone needs no radar zone.",
  "Different limit while driving": "Different limit while driving",
  "Each zone has its own Radar and Exclusive rules, its radar zones drawn on the map, and what the driver app shows.": "Each zone has its own Radar and Exclusive rules, its radar zones drawn on the map, and what the driver app shows.",
  "Each zone has its own rules: the best driver, what the rider sees while waiting, rides and stops, and more. Radar, Exclusive and reservations have their own section.": "Each zone has its own rules: the best driver, what the rider sees while waiting, rides and stops, and more. Radar, Exclusive and reservations have their own section.",
  "Every Radar, Exclusive and reservation rule is set there, in one place.": "Every Radar, Exclusive and reservation rule is set there, in one place.",
